CREATE OR REPLACE FUNCTION public.fn_get_child_journey_insight_items(p_tenant_id uuid, p_request_id uuid)  RETURNS TABLE(id uuid, request_id uuid, tenant_id uuid, category character varying, classification character varying, statement text, evidence_strength character varying, supporting_evidence text, suggested_experience_id uuid, suggested_experience_title character varying, rank_order integer, created_at timestamp with time zone)  LANGUAGE sql  STABLE AS $function$     SELECT          id, request_id, tenant_id, category, classification,         statement, evidence_strength, supporting_evidence::text,         suggested_experience_id, suggested_experience_title,         rank_order, created_at     FROM child_journey_insight_items     WHERE tenant_id = p_tenant_id AND request_id = p_request_id     ORDER BY rank_order ASC; $function$ ;
